const fs = require('fs');
const { execSync } = require('child_process');

const repoPath = '/tmp/autobrain-approval-watcher';

// Clone or pull latest
if (!fs.existsSync(repoPath)) {
  execSync(`git clone https://github.com/CannonFodder151/autobrain.git ${repoPath}`);
} else {
  execSync(`cd ${repoPath} && git pull origin main`);
}

// Run approval watcher
const result = execSync('python3 scripts/approval_watcher.py', {
  cwd: repoPath,
  env: {
    ...process.env,
    DISCORD_BOT_TOKEN: $env.DISCORD_BOT_TOKEN,
    DISCORD_CHANNEL_MARKETING: $env.DISCORD_CHANNEL_MARKETING,
    NATHAN_DISCORD_ID: $env.NATHAN_DISCORD_ID,
    PAPERCLIP_API_URL: $env.PAPERCLIP_API_URL,
    PAPERCLIP_API_KEY: $env.PAPERCLIP_API_KEY,
    PAPERCLIP_COMPANY_ID: $env.PAPERCLIP_COMPANY_ID,
    PAPERCLIP_RUN_ID: 'n8n-approval-watcher-'+Date.now()
  },
  encoding: 'utf8',
  maxBuffer: 10 * 1024 * 1024
});

return [{ json: { success: true, output: result.toString() } }];
